SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷102·隐帝本纪·乾祐二年十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7852147b76d0b357a666a03e1c8d219918bae3dc/content/books/zizhi-tongjian/vol-288/year-0949/part-05/sources/library/jiuwudaishi-102-december-949/source.txt", "note": "《旧五代史》卷102·隐帝本纪·乾祐二年十二月，段落 jiu-wudaishi-205deb4a7860-p002480；已核上下文及传主，纸本及异文待核。", "id": "2bf89acb-470a-5d02-8687-c6c52aff718e"}, {"title": "旧五代史·卷102·隐帝本纪·乾祐二年十月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7852147b76d0b357a666a03e1c8d219918bae3dc/content/books/zizhi-tongjian/vol-288/year-0949/part-05/sources/library/jiuwudaishi-102-october-949/source.txt", "note": "《旧五代史》卷102·隐帝本纪·乾祐二年十月，段落 jiu-wudaishi-205deb4a7860-p002478；已核上下文及传主，纸本及异文待核。", "id": "c13a4bc7-de91-5a2b-87ce-68d6b3bd4dcf"}, {"title": "辽史·卷5·世宗纪·天禄三年十月", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7852147b76d0b357a666a03e1c8d219918bae3dc/content/books/zizhi-tongjian/vol-288/year-0949/part-05/sources/library/liaoshi-005-hebei-949/source.txt", "note": "《辽史》卷5·世宗纪·天禄三年十月，段落 liaoshi-7cd182a20e67-p000606；已核上下文及传主，纸本及异文待核。", "id": "8f9e2c4e-d1f4-5abc-8dea-4cc0d951a66b"}, {"title": "新五代史·卷18·汉家人传·刘赟亲支", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7852147b76d0b357a666a03e1c8d219918bae3dc/content/books/zizhi-tongjian/vol-288/year-0949/part-05/sources/library/xinwudaishi-018-liu-yun-identity/source.txt", "note": "《新五代史》卷18·汉家人传·刘赟亲支，段落 xin-wudaishi-b08f244b9241-p000624；已核上下文及传主，纸本及异文待核。", "id": "6d1a97fd-fae4-5cfc-9205-a878601a84f7"}, {"title": "资治通鉴·卷288·乾祐二年·八月至十二月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d5546bb3510d89dd7f3f66087f55d50b7752ed/content/books/zizhi-tongjian/vol-288/year-0949/part-04/sources/library/tongjian-288-949-august-december/source.txt", "note": "《资治通鉴》卷288·乾祐二年·八月至十二月，段落 zizhi-tongjian-a63549944a71-p003425；已核上下文及传主，纸本及异文待核。", "id": "bf2b74b2-dd3d-5a7c-b003-9f3556a7ff38"}, {"title": "旧五代史·卷102·隐帝本纪·乾祐二年九月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d5546bb3510d89dd7f3f66087f55d50b7752ed/content/books/zizhi-tongjian/vol-288/year-0949/part-04/sources/library/jiuwudaishi-102-september-949/source.txt", "note": "《旧五代史》卷102·隐帝本纪·乾祐二年九月，段落 jiu-wudaishi-205deb4a7860-p002477；已核上下文及传主，纸本及异文待核。", "id": "91eb68a3-3957-55b7-962a-8fb9e4be5cd5"}, {"title": "旧五代史·卷110·周太祖纪·乾祐二年八月返京", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d5546bb3510d89dd7f3f66087f55d50b7752ed/content/books/zizhi-tongjian/vol-288/year-0949/part-04/sources/library/jiuwudaishi-110-return-court-949/source.txt", "note": "《旧五代史》卷110·周太祖纪·乾祐二年八月返京，段落 jiu-wudaishi-205deb4a7860-p002636；已核上下文及传主，纸本及异文待核。", "id": "393a6c8f-d7a4-5dc9-8d5f-6a6b81a64875"}]'::jsonb)
